import React from 'react';
import { DashboardCard } from '@/components/client/DashboardCard';
import { Calendar, User, Scissors, Clock } from 'lucide-react';

export default function ClientDashboard() {
    return (
        <div className="p-6 space-y-6">
            <h1 className="text-2xl font-light text-white">Dashboard</h1>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <DashboardCard
                    title="Próximo Atendimento"
                    value="15/09/2026"
                    icon={<Calendar className="w-6 h-6" />}
                    bgColor="bg-[var(--color-dark-card)]"
                />
                <DashboardCard
                    title="Barbeiro Escolhido"
                    value="Marcelo"
                    icon={<User className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Serviço Agendado"
                    value="Corte + Barba"
                    icon={<Scissors className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Horário Marcado"
                    value="10:30"
                    icon={<Clock className="w-6 h-6" />}
                />
            </div>
            <div className="flex justify-end mt-4">
                <a href="/client/schedule" className="px-4 py-2 bg-[var(--color-primary-gold)] text-black rounded-lg hover:bg-[var(--color-primary-gold-hover)] transition-colors">
                    Agendar Horário
                </a>
            </div>
        </div>
    );
}
